import{_ as a,o,c as t,a2 as r}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Spectre","description":"","frontmatter":{"title":"Spectre","order":12},"headers":[],"relativePath":"zh/mods/spectre.md","filePath":"zh/mods/spectre.md","lastUpdated":1786943111000}'),l={name:"zh/mods/spectre.md"};function i(n,e,s,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="spectre" tabindex="-1">Spectre <a class="header-anchor" href="#spectre" aria-label="Permalink to &quot;Spectre&quot;">​</a></h1><blockquote><p>ADOFAI <strong>回放 Mod</strong>，基于 Harmony 与 UnityModManager 构建，精确录制与回放键盘输入。</p><p>项目地址：<a href="https://github.com/adofaiex/Spectre" target="_blank" rel="noreferrer">https://github.com/adofaiex/Spectre</a></p></blockquote><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><h3 id="回放系统" tabindex="-1">回放系统 <a class="header-anchor" href="#回放系统" aria-label="Permalink to &quot;回放系统&quot;">​</a></h3><p><strong>录制</strong></p><ul><li>捕获每个键盘事件（按下/松开），带精确的歌曲位置时间戳</li><li>逐块记录命中上下文：角度、过载、自动状态、no-fail 保护、free-roam 段</li><li>命中分布与 X-accuracy 追踪</li><li>可选：通过麦克风录制键盘音效（随回放以 <code>.wav</code> 保存）</li><li>晚存 / 失败存 / 自动存三种存档模式</li><li>退出关卡前手动保存</li></ul><p><strong>回放</strong></p><ul><li>逐块回放，精确还原角度 / 自动 / 过载状态</li><li>支持整段回放与检查点回放</li><li>快进到起始检查点</li><li>可选旧版命中检测引擎</li><li>加载时校验数据完整性（对地板路径、速度、时间、音高、BPM 做哈希校验）</li></ul><h3 id="特效去除-effect-remover" tabindex="-1">特效去除（Effect Remover） <a class="header-anchor" href="#特效去除-effect-remover" aria-label="Permalink to &quot;特效去除（Effect Remover）&quot;">​</a></h3><ul><li><strong>星球</strong>：轨道（Orbit）、缩放（Scale）、半径（Radius）</li><li><strong>轨道</strong>：动画、位置、移动、颜色</li><li><strong>DLC</strong>：长按音效（Hold Sounds）、隐藏图标（Hide Icons）</li><li><strong>其他</strong>：移除所有装饰（或保留受条件事件标记的）、重置轨道透明度 / 动画 / 颜色、设置相机缩放</li></ul><p>覆盖设置：<code>Remove All Decorations</code>（清除除条件事件标记外的所有装饰）、<code>Set Camera Zoom</code>（覆盖相机缩放 100–1000）、<code>Reset Track Animation/Color</code>。游戏与编辑器均可用；特效去除激活时编辑器保存按钮被禁用（可配置）。</p><h3 id="按键重映射" tabindex="-1">按键重映射 <a class="header-anchor" href="#按键重映射" aria-label="Permalink to &quot;按键重映射&quot;">​</a></h3><p>通过 <code>Options.UI</code> 页签在运行时重映射按键，适合自定义键盘布局或跨平台输入处理。</p><h3 id="音频录制" tabindex="-1">音频录制 <a class="header-anchor" href="#音频录制" aria-label="Permalink to &quot;音频录制&quot;">​</a></h3><p>通过连接的麦克风录制键盘音效，音量与偏移可调。音频与回放文件一同保存，回放时按哈希校验。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>为 ADOFAI 安装 <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">UnityModManager</a></li><li>把 <code>Spectre.dll</code> 放到 <code>UnityModManager/ADofAI/Mods/Spectre/</code></li><li>启动游戏，在 Mod 管理器中启用 Spectre</li></ol><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>首次启动时在 DLL 旁自动生成 <code>Configs.json</code>，所有设置均可在游戏内 UI 中调整（从 UnityModManager Mod 列表打开）。</p><p>设置分为 6 个页签：</p><ul><li><strong>Save Settings</strong> —— 自动存、完成存、晚存、失败存、手动存、备份、旧版引擎、auto/miss 时不保存</li><li><strong>Replaying Settings</strong> —— 回放速度、保存按钮位置、按键上限</li><li><strong>Audio Record Settings</strong> —— 键盘音效录制、音量、麦克风设备、偏移</li><li><strong>Mod UI</strong> —— 字号、语言、按键重映射</li><li><strong>Debug Settings</strong> —— 按键校验、调试模式、跳过校验</li><li><strong>Effect Remover</strong> —— 逐项特效开关</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>回放格式参考与 Harmony 补丁工具：<a href="./yqlossclientharmony">YqlossClientHarmony</a></li><li>另一个 ADOFAI 回放 Mod：<a href="https://github.com/potatoonadofai/Creplay-mod" target="_blank" rel="noreferrer">Creplay-mod</a></li></ul>',23)])])}const g=a(l,[["render",i]]);export{u as __pageData,g as default};
